using System;
using System.Collections;
using UnityEngine;
using InControl;
using Framework.Input;
using Framework.Save.Integrations.EasySave;
using Game.Input;

namespace Game.Tests
{
    /// <summary>
    /// GameInputManagerの動作確認用クラス。
    ///
    /// 入力システムの初期化、操作登録、
    /// 入力モードの切り替え、入力制御を検証する。
    ///
    /// 自動テスト終了後は手動入力テストへ移行する。
    /// 本番のキー設定ファイルは変更しない。
    /// </summary>
    public class GameInputManagerTest : MonoBehaviour
    {
        #region Inspector Fields

        [Header("参照設定")]

        /// <summary>テスト対象の入力管理クラス。</summary>
        [SerializeField]
        [Tooltip("テスト対象のGameInputManager")]
        private GameInputManager inputManager;

        [Header("テスト設定")]

        /// <summary>開始時に自動テストを実行するか。</summary>
        [SerializeField]
        [Tooltip("開始時に全自動テストを実行する")]
        private bool runTestsOnStart = true;

        /// <summary>手動入力テストを有効にするか。</summary>
        [SerializeField]
        [Tooltip("自動テスト終了後に手動入力を確認する")]
        private bool enableManualTest = true;

        /// <summary>方向入力のデッドゾーン。</summary>
        [SerializeField]
        [Range(0f, 0.99f)]
        [Tooltip("方向入力を無視する範囲")]
        private float deadZone = 0.3f;

        [Header("現在の入力状態（確認用）")]

        /// <summary>現在の入力モード。</summary>
        [SerializeField]
        private GameInputMode currentMode;

        /// <summary>現在の移動入力ベクトル。</summary>
        [SerializeField]
        private Vector2 moveInput;

        /// <summary>上下左右に変換した移動方向。</summary>
        [SerializeField]
        private Vector2Int moveDirection;

        /// <summary>現在のUI方向入力。</summary>
        [SerializeField]
        private Vector2 navigateInput;

        /// <summary>現在のUI操作方向。</summary>
        [SerializeField]
        private Vector2Int navigateDirection;

        /// <summary>アイテム使用ボタンの押下状態。</summary>
        [SerializeField]
        private bool useItemPressed;

        /// <summary>召喚ボタンの押下状態。</summary>
        [SerializeField]
        private bool summonPressed;

        /// <summary>決定ボタンの押下状態。</summary>
        [SerializeField]
        private bool submitPressed;

        /// <summary>キャンセルボタンの押下状態。</summary>
        [SerializeField]
        private bool cancelPressed;

        [Header("テスト結果（確認用）")]

        /// <summary>成功したテスト項目数。</summary>
        [SerializeField]
        private int passedCount;

        /// <summary>失敗したテスト項目数。</summary>
        [SerializeField]
        private int failedCount;

        #endregion

        #region Runtime Fields

        /// <summary>自動テストを実行中か。</summary>
        private bool isTesting;

        /// <summary>手動テストの準備が完了しているか。</summary>
        private bool isManualTestReady;

        /// <summary>前回の移動方向。</summary>
        private Vector2Int previousMoveDirection;

        /// <summary>前回のUI操作方向。</summary>
        private Vector2Int previousNavigateDirection;

        /// <summary>入力モード変更イベントの発生回数。</summary>
        private int modeChangedCount;

        /// <summary>テスト専用の保存Provider。</summary>
        private EasySaveProvider testSaveProvider;

        /// <summary>実行中の自動テスト。</summary>
        private Coroutine testCoroutine;

        #endregion

        #region Unity Methods

        /// <summary>シーン開始時の処理。</summary>
        private void Start()
        {
            if (!ValidateReferences())
            {
                return;
            }

            inputManager.InputModeChanged +=
                OnInputModeChanged;

            if (runTestsOnStart)
            {
                RunAllTests();
            }
            else
            {
                PrepareManualTest();
            }
        }

        /// <summary>
        /// 毎フレームの手動入力確認処理。
        /// 自動テスト中は実行しない。
        /// </summary>
        private void Update()
        {
            if (isTesting ||
                !enableManualTest ||
                !isManualTestReady ||
                inputManager == null ||
                !inputManager.IsInitialized)
            {
                return;
            }

            UpdateInputState();
            ProcessGameplayInput();
            ProcessUIInput();
        }

        /// <summary>
        /// コンポーネント無効化時の処理。
        /// 実行中のテストを中断する。
        /// </summary>
        private void OnDisable()
        {
            if (testCoroutine != null)
            {
                StopCoroutine(testCoroutine);
                testCoroutine = null;
            }

            isTesting = false;
            isManualTestReady = false;
        }

        /// <summary>コンポーネント破棄時の解放処理。</summary>
        private void OnDestroy()
        {
            if (inputManager != null)
            {
                inputManager.InputModeChanged -=
                    OnInputModeChanged;
            }

            CleanupTestSaveProvider();
        }

        #endregion

        #region Validation Methods

        /// <summary>
        /// テストに必要な参照を確認する。
        /// </summary>
        /// <returns>参照が正常な場合はtrue</returns>
        private bool ValidateReferences()
        {
            if (inputManager == null)
            {
                Debug.LogError(
                    "GameInputManagerが設定されていません。",
                    this);

                return false;
            }

            if (!inputManager.gameObject.activeInHierarchy)
            {
                Debug.LogError(
                    "GameInputManagerのGameObjectを" +
                    "有効にしてください。",
                    this);

                return false;
            }

            return true;
        }

        #endregion

        #region Test Control Methods

        /// <summary>すべての自動テストを実行する。</summary>
        [ContextMenu("テスト/全自動テストを実行する")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "再生モードで実行してください。",
                    this);

                return;
            }

            if (isTesting || !ValidateReferences())
            {
                return;
            }

            isTesting = true;
            isManualTestReady = false;

            testCoroutine =
                StartCoroutine(RunAllTestsCoroutine());
        }

        /// <summary>
        /// フレームをまたいで入力管理機能を検証する。
        /// </summary>
        /// <returns>テスト実行用IEnumerator</returns>
        private IEnumerator RunAllTestsCoroutine()
        {
            passedCount = 0;
            failedCount = 0;
            modeChangedCount = 0;

            Debug.Log(
                "【GameInputManager 自動テスト開始】",
                this);

            // テスト専用の入力環境を準備する。
            if (!InitializeTestManager())
            {
                Check(false, "テスト環境の初期化");

                FinishTests();
                yield break;
            }

            // 初期化フレームの入力遮断解除を待つ。
            yield return null;

            TestInitialization();
            TestActionRegistration();
            TestActionLookup();

            // Gameplayモードの検証。
            inputManager.SetInputMode(
                GameInputMode.Gameplay);

            yield return null;

            TestGameplayMode();

            // UIモードへ切り替えた直後の状態を検証する。
            TestModeChangeBlocking();

            yield return null;

            TestUIMode();

            // Bothモードの検証。
            inputManager.SetInputMode(
                GameInputMode.Both);

            yield return null;

            TestBothMode();

            // 入力全体の無効化を検証する。
            TestGlobalInputDisable();

            inputManager.SetInputEnabled(true);

            yield return null;

            Check(
                inputManager.IsInputEnabled,
                "入力全体の再有効化");

            // Disabledモードの検証。
            inputManager.SetInputMode(
                GameInputMode.Disabled);

            yield return null;

            TestDisabledMode();

            // コンポーネントの有効・無効を検証する。
            inputManager.SetInputMode(
                GameInputMode.Gameplay);

            yield return null;

            inputManager.enabled = false;

            Check(
                !inputManager.IsInputEnabled,
                "コンポーネント無効化時の入力停止");

            inputManager.enabled = true;

            yield return null;

            Check(
                inputManager.IsGameplayInputEnabled,
                "コンポーネント再有効化時の入力復元");

            TestDuplicateMode();
            TestInvalidMode();
            TestResetBindings();

            // 終了・再初期化を検証する。
            TestShutdown();

            Check(
                inputManager.Initialize(
                    testSaveProvider,
                    false),
                "入力システムの再初期化");

            yield return null;

            Check(
                inputManager.IsInitialized,
                "再初期化後の初期化状態");

            Check(
                inputManager.ActionCount == 17,
                "再初期化後の操作登録数");

            FinishTests();
        }

        /// <summary>
        /// テスト専用の保存先を使用してManagerを初期化する。
        /// </summary>
        /// <returns>初期化に成功した場合はtrue</returns>
        private bool InitializeTestManager()
        {
            try
            {
                inputManager.Shutdown();

                CleanupTestSaveProvider();

                // 本番の保存データとの競合を防ぐ。
                string testId =
                    Guid.NewGuid().ToString("N");

                testSaveProvider =
                    new EasySaveProvider(
                        $"Tests/GameInput_{testId}.es3");

                inputManager.enabled = true;

                return inputManager.Initialize(
                    testSaveProvider,
                    false);
            }
            catch (Exception exception)
            {
                Debug.LogException(exception, this);

                return false;
            }
        }

        /// <summary>
        /// 自動テストを終了して結果を出力する。
        /// </summary>
        private void FinishTests()
        {
            isTesting = false;
            testCoroutine = null;

            PrintTestResult();

            if (failedCount == 0 && enableManualTest)
            {
                PrepareManualTest();
            }
        }

        /// <summary>テスト専用の保存ファイルを削除する。</summary>
        private void CleanupTestSaveProvider()
        {
            if (testSaveProvider == null)
            {
                return;
            }

            try
            {
                testSaveProvider.DeleteAll();
            }
            catch (Exception exception)
            {
                Debug.LogWarning(
                    $"テストファイルの削除失敗：" +
                    exception.Message,
                    this);
            }

            testSaveProvider = null;
        }

        #endregion

        #region Automated Test Methods

        /// <summary>初期化状態を検証する。</summary>
        private void TestInitialization()
        {
            Check(
                inputManager.IsInitialized,
                "Managerの初期化");

            Check(
                inputManager.HasSaveProvider,
                "保存Providerの設定");

            Check(
                !inputManager.IsInputBlocked,
                "初期化後の入力遮断解除");

            Check(
                inputManager.isActiveAndEnabled,
                "コンポーネントの有効状態");

            Check(
                !inputManager.HasSavedBindings(),
                "テスト専用保存領域の独立性");
        }

        /// <summary>操作IDの登録状態を検証する。</summary>
        private void TestActionRegistration()
        {
            Check(
                inputManager.GameplayActionCount == 8,
                "Gameplay操作登録数");

            Check(
                inputManager.UIActionCount == 9,
                "UI操作登録数");

            Check(
                inputManager.ActionCount == 17,
                "全操作登録数");

            foreach (GameInputAction action in
                Enum.GetValues(typeof(GameInputAction)))
            {
                if (action == GameInputAction.None)
                {
                    continue;
                }

                Check(
                    inputManager.HasAction(action),
                    $"操作登録：{action}");
            }

            Check(
                !inputManager.HasAction(
                    GameInputAction.None),
                "Noneが未登録であること");
        }

        /// <summary>個別操作の取得処理を検証する。</summary>
        private void TestActionLookup()
        {
            Check(
                inputManager.TryGetPlayerAction(
                    GameInputAction.MoveUp,
                    out PlayerAction moveUp) &&
                moveUp != null,
                "MoveUpの取得");

            Check(
                inputManager.TryGetPlayerAction(
                    GameInputAction.UseItem,
                    out PlayerAction useItem) &&
                useItem != null,
                "UseItemの取得");

            Check(
                inputManager.TryGetPlayerAction(
                    GameInputAction.Submit,
                    out PlayerAction submit) &&
                submit != null,
                "Submitの取得");

            Check(
                !inputManager.TryGetPlayerAction(
                    GameInputAction.Move,
                    out _),
                "2軸操作の個別ボタン取得拒否");

            Check(
                !inputManager.TryGetPlayerAction(
                    GameInputAction.None,
                    out _),
                "未登録操作の取得拒否");

            Check(
                !inputManager.HasAction(
                    (GameInputAction)99999),
                "不明な操作IDの拒否");
        }

        /// <summary>Gameplayモードを検証する。</summary>
        private void TestGameplayMode()
        {
            Check(
                inputManager.CurrentMode ==
                GameInputMode.Gameplay,
                "Gameplayモードの設定");

            Check(
                inputManager.IsGameplayInputEnabled,
                "Gameplay入力の有効化");

            Check(
                !inputManager.IsUIInputEnabled,
                "UI入力の無効化");

            Check(
                inputManager.GetVector2(
                    GameInputAction.Navigate) ==
                Vector2.zero,
                "無効なUI方向入力の遮断");

            Check(
                !inputManager.GetButton(
                    GameInputAction.Submit),
                "無効なUIボタン入力の遮断");
        }

        /// <summary>
        /// モード変更フレームの入力遮断を検証する。
        /// </summary>
        private void TestModeChangeBlocking()
        {
            modeChangedCount = 0;

            Check(
                inputManager.SetInputMode(
                    GameInputMode.UI),
                "UIモードへの切り替え");

            Check(
                inputManager.CurrentMode ==
                GameInputMode.UI,
                "変更後の入力モード");

            Check(
                modeChangedCount == 1,
                "入力モード変更イベント");

            Check(
                inputManager.IsInputBlocked,
                "変更フレームの入力遮断");

            Check(
                !inputManager.IsInputEnabled,
                "変更フレームの入力無効化");

            Check(
                inputManager.GetVector2(
                    GameInputAction.Navigate) ==
                Vector2.zero,
                "変更フレームの方向入力遮断");
        }

        /// <summary>UIモードを検証する。</summary>
        private void TestUIMode()
        {
            Check(
                !inputManager.IsInputBlocked,
                "翌フレームの入力遮断解除");

            Check(
                inputManager.IsUIInputEnabled,
                "UI入力の有効化");

            Check(
                !inputManager.IsGameplayInputEnabled,
                "Gameplay入力の無効化");

            Check(
                inputManager.GetVector2(
                    GameInputAction.Move) ==
                Vector2.zero,
                "無効な移動入力の遮断");

            Check(
                !inputManager.GetButton(
                    GameInputAction.UseItem),
                "無効なアイテム入力の遮断");
        }

        /// <summary>Bothモードを検証する。</summary>
        private void TestBothMode()
        {
            Check(
                inputManager.CurrentMode ==
                GameInputMode.Both,
                "Bothモードの設定");

            Check(
                inputManager.IsGameplayInputEnabled,
                "BothモードのGameplay入力");

            Check(
                inputManager.IsUIInputEnabled,
                "BothモードのUI入力");
        }

        /// <summary>入力全体の無効化を検証する。</summary>
        private void TestGlobalInputDisable()
        {
            inputManager.SetInputEnabled(false);

            Check(
                !inputManager.IsInputEnabled,
                "入力全体の無効化");

            Check(
                !inputManager.IsGameplayInputEnabled,
                "Gameplay入力の停止");

            Check(
                !inputManager.IsUIInputEnabled,
                "UI入力の停止");

            Check(
                !inputManager.GetButton(
                    GameInputAction.UseItem),
                "GetButtonの無効化");

            Check(
                !inputManager.GetButtonDown(
                    GameInputAction.UseItem),
                "GetButtonDownの無効化");

            Check(
                !inputManager.GetButtonUp(
                    GameInputAction.UseItem),
                "GetButtonUpの無効化");

            Check(
                inputManager.GetAxis(
                    GameInputAction.MoveUp) == 0f,
                "GetAxisの無効化");

            Check(
                inputManager.GetVector2(
                    GameInputAction.Move) ==
                Vector2.zero,
                "GetVector2の無効化");

            Check(
                inputManager.CurrentMode ==
                GameInputMode.Both,
                "無効化前の入力モード維持");
        }

        /// <summary>Disabledモードを検証する。</summary>
        private void TestDisabledMode()
        {
            Check(
                inputManager.CurrentMode ==
                GameInputMode.Disabled,
                "Disabledモードの設定");

            Check(
                !inputManager.IsInputEnabled,
                "Disabledモードの入力停止");

            Check(
                !inputManager.IsGameplayInputEnabled &&
                !inputManager.IsUIInputEnabled,
                "全操作セットの無効化");
        }

        /// <summary>同一モードの再指定を検証する。</summary>
        private void TestDuplicateMode()
        {
            modeChangedCount = 0;

            Check(
                inputManager.SetInputMode(
                    inputManager.CurrentMode),
                "同一モードの再指定");

            Check(
                modeChangedCount == 0,
                "不要な変更イベントの防止");
        }

        /// <summary>不正な入力モードを検証する。</summary>
        private void TestInvalidMode()
        {
            GameInputMode previousMode =
                inputManager.CurrentMode;

            bool exceptionThrown = false;

            try
            {
                inputManager.SetInputMode(
                    (GameInputMode)99999);
            }
            catch (ArgumentOutOfRangeException)
            {
                exceptionThrown = true;
            }

            Check(
                exceptionThrown,
                "不正な入力モードの拒否");

            Check(
                inputManager.CurrentMode == previousMode,
                "不正なモード指定時の状態維持");
        }

        /// <summary>キー設定の初期化を検証する。</summary>
        private void TestResetBindings()
        {
            Check(
                inputManager.ResetBindings(),
                "キー設定の初期化");

            Check(
                inputManager.ActionCount == 17,
                "キー設定初期化後の操作登録維持");
        }

        /// <summary>入力システムの終了処理を検証する。</summary>
        private void TestShutdown()
        {
            inputManager.Shutdown();

            Check(
                !inputManager.IsInitialized,
                "入力システムの終了");

            Check(
                !inputManager.IsInputEnabled,
                "終了後の入力停止");

            Check(
                inputManager.ActionCount == 0,
                "終了後の操作登録解除");

            Check(
                !inputManager.HasSaveProvider,
                "終了後の保存Provider解除");

            Check(
                inputManager.CurrentMode ==
                GameInputMode.Disabled,
                "終了後の入力モード");

            Check(
                !inputManager.HasAction(
                    GameInputAction.MoveUp),
                "終了後の操作取得拒否");
        }

        #endregion

        #region Manual Test Methods

        /// <summary>手動入力テストを準備する。</summary>
        private void PrepareManualTest()
        {
            if (!enableManualTest ||
                !ValidateReferences())
            {
                return;
            }

            if (testSaveProvider == null ||
                !inputManager.IsInitialized)
            {
                if (!InitializeTestManager())
                {
                    return;
                }
            }

            inputManager.SetInputEnabled(true);

            inputManager.SetInputMode(
                GameInputMode.Gameplay);

            previousMoveDirection = Vector2Int.zero;
            previousNavigateDirection = Vector2Int.zero;

            isManualTestReady = true;

            Debug.Log(
                "【手動入力テスト開始】\n" +
                "WASD・矢印キー：移動\n" +
                "Space：アイテム使用\n" +
                "E：召喚\n" +
                "Esc：UIモードへ切り替え\n" +
                "UIモードのEsc：Gameplayへ戻る",
                this);
        }

        /// <summary>
        /// 現在の入力状態をInspector確認用に更新する。
        /// </summary>
        private void UpdateInputState()
        {
            currentMode = inputManager.CurrentMode;

            moveInput = inputManager.GetVector2(
                GameInputAction.Move);

            moveDirection =
                InputDirectionUtility.ToFourDirection(
                    moveInput,
                    deadZone,
                    DirectionPriority.PreviousDirection,
                    previousMoveDirection);

            navigateInput = inputManager.GetVector2(
                GameInputAction.Navigate);

            navigateDirection =
                InputDirectionUtility.ToFourDirection(
                    navigateInput,
                    deadZone,
                    DirectionPriority.PreviousDirection,
                    previousNavigateDirection);

            useItemPressed = inputManager.GetButton(
                GameInputAction.UseItem);

            summonPressed = inputManager.GetButton(
                GameInputAction.Summon);

            submitPressed = inputManager.GetButton(
                GameInputAction.Submit);

            cancelPressed = inputManager.GetButton(
                GameInputAction.Cancel);
        }

        /// <summary>ゲーム操作の手動入力を検証する。</summary>
        private void ProcessGameplayInput()
        {
            if (!inputManager.IsGameplayInputEnabled)
            {
                previousMoveDirection = Vector2Int.zero;
                return;
            }

            // 入力方向が変化した場合のみログを出力する。
            if (moveDirection != previousMoveDirection)
            {
                Debug.Log(
                    $"[Gameplay] 移動方向：" +
                    $"{GetDirectionName(moveDirection)} " +
                    $"{moveDirection}",
                    this);

                previousMoveDirection = moveDirection;
            }

            if (inputManager.GetButtonDown(
                GameInputAction.UseItem))
            {
                Debug.Log(
                    "[Gameplay] アイテム使用：押下",
                    this);
            }

            if (inputManager.GetButtonUp(
                GameInputAction.UseItem))
            {
                Debug.Log(
                    "[Gameplay] アイテム使用：解放",
                    this);
            }

            if (inputManager.GetButtonDown(
                GameInputAction.Summon))
            {
                Debug.Log(
                    "[Gameplay] 召喚：押下",
                    this);
            }

            if (inputManager.GetButtonUp(
                GameInputAction.Summon))
            {
                Debug.Log(
                    "[Gameplay] 召喚：解放",
                    this);
            }

            if (inputManager.GetButtonDown(
                GameInputAction.Pause))
            {
                Debug.Log(
                    "[Gameplay] ポーズ操作",
                    this);

                inputManager.SetInputMode(
                    GameInputMode.UI);
            }
        }

        /// <summary>UI操作の手動入力を検証する。</summary>
        private void ProcessUIInput()
        {
            if (!inputManager.IsUIInputEnabled)
            {
                previousNavigateDirection =
                    Vector2Int.zero;

                return;
            }

            if (navigateDirection !=
                previousNavigateDirection)
            {
                Debug.Log(
                    $"[UI] 操作方向：" +
                    $"{GetDirectionName(navigateDirection)} " +
                    $"{navigateDirection}",
                    this);

                previousNavigateDirection =
                    navigateDirection;
            }

            if (inputManager.GetButtonDown(
                GameInputAction.Submit))
            {
                Debug.Log("[UI] 決定", this);
            }

            if (inputManager.GetButtonDown(
                GameInputAction.PreviousTab))
            {
                Debug.Log("[UI] 前のタブ", this);
            }

            if (inputManager.GetButtonDown(
                GameInputAction.NextTab))
            {
                Debug.Log("[UI] 次のタブ", this);
            }

            if (inputManager.GetButtonDown(
                GameInputAction.Cancel))
            {
                Debug.Log("[UI] キャンセル", this);

                inputManager.SetInputMode(
                    GameInputMode.Gameplay);
            }
        }

        #endregion

        #region Context Menu Methods

        /// <summary>Gameplayモードへ切り替える。</summary>
        [ContextMenu("手動テスト/Gameplayモード")]
        private void SetGameplayMode()
        {
            SetManualMode(GameInputMode.Gameplay);
        }

        /// <summary>UIモードへ切り替える。</summary>
        [ContextMenu("手動テスト/UIモード")]
        private void SetUIMode()
        {
            SetManualMode(GameInputMode.UI);
        }

        /// <summary>Bothモードへ切り替える。</summary>
        [ContextMenu("手動テスト/Bothモード")]
        private void SetBothMode()
        {
            SetManualMode(GameInputMode.Both);
        }

        /// <summary>Disabledモードへ切り替える。</summary>
        [ContextMenu("手動テスト/Disabledモード")]
        private void SetDisabledMode()
        {
            SetManualMode(GameInputMode.Disabled);
        }

        /// <summary>入力全体を有効化する。</summary>
        [ContextMenu("手動テスト/入力を有効化")]
        private void EnableInput()
        {
            if (CanExecuteManualCommand())
            {
                inputManager.SetInputEnabled(true);

                Debug.Log("入力を有効化しました。", this);
            }
        }

        /// <summary>入力全体を無効化する。</summary>
        [ContextMenu("手動テスト/入力を無効化")]
        private void DisableInput()
        {
            if (CanExecuteManualCommand())
            {
                inputManager.SetInputEnabled(false);

                Debug.Log("入力を無効化しました。", this);
            }
        }

        /// <summary>現在の入力管理状態を出力する。</summary>
        [ContextMenu("手動テスト/現在の状態を表示")]
        private void PrintCurrentState()
        {
            if (!CanExecuteManualCommand())
            {
                return;
            }

            Debug.Log(
                "【現在の入力状態】\n" +
                $"初期化：{inputManager.IsInitialized}\n" +
                $"モード：{inputManager.CurrentMode}\n" +
                $"入力有効：{inputManager.IsInputEnabled}\n" +
                $"入力遮断：{inputManager.IsInputBlocked}\n" +
                $"Gameplay：" +
                $"{inputManager.IsGameplayInputEnabled}\n" +
                $"UI：{inputManager.IsUIInputEnabled}\n" +
                $"登録操作数：{inputManager.ActionCount}\n" +
                $"移動入力：{moveInput}\n" +
                $"移動方向：{moveDirection}\n" +
                $"UI入力：{navigateInput}",
                this);
        }

        /// <summary>
        /// 手動テスト用の入力モードを設定する。
        /// </summary>
        /// <param name="mode">変更後の入力モード</param>
        private void SetManualMode(GameInputMode mode)
        {
            if (CanExecuteManualCommand())
            {
                inputManager.SetInputMode(mode);
            }
        }

        /// <summary>
        /// 手動テスト用コマンドを実行できるか確認する。
        /// </summary>
        /// <returns>実行可能な場合はtrue</returns>
        private bool CanExecuteManualCommand()
        {
            return Application.isPlaying &&
                   !isTesting &&
                   inputManager != null &&
                   inputManager.IsInitialized;
        }

        #endregion

        #region Event Methods

        /// <summary>
        /// 入力モード変更時のイベント処理。
        /// </summary>
        /// <param name="previousMode">変更前のモード</param>
        /// <param name="newMode">変更後のモード</param>
        private void OnInputModeChanged(
            GameInputMode previousMode,
            GameInputMode newMode)
        {
            modeChangedCount++;

            currentMode = newMode;

            Debug.Log(
                $"[入力モード変更] " +
                $"{previousMode} → {newMode}",
                this);
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 方向ベクトルを確認用の日本語文字列へ変換する。
        /// </summary>
        /// <param name="direction">変換する方向</param>
        /// <returns>方向を表す文字列</returns>
        private static string GetDirectionName(
            Vector2Int direction)
        {
            if (direction == Vector2Int.up)
            {
                return "上";
            }

            if (direction == Vector2Int.down)
            {
                return "下";
            }

            if (direction == Vector2Int.left)
            {
                return "左";
            }

            if (direction == Vector2Int.right)
            {
                return "右";
            }

            return "入力なし";
        }

        /// <summary>テスト結果を記録する。</summary>
        /// <param name="condition">成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        /// <summary>自動テストの集計結果を出力する。</summary>
        private void PrintTestResult()
        {
            string message =
                "【GameInputManager テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message +
                    "\nすべての自動テストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

        #endregion
    }
}
